<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import type {MatchingData} from '../../electron/types'
import {matchingAnswer,parseMatchingAnswer} from '../../electron/matching'
import AssetImage from './AssetImage.vue'
const props=defineProps<{data:MatchingData;modelValue:string;readonly?:boolean;showAnswer?:boolean}>(),emit=defineEmits<{'update:modelValue':[value:string]}>()
const root=ref<HTMLElement>(),selected=ref<string|null>(null),lines=ref<{key:string;x1:number;y1:number;x2:number;y2:number}[]>([])
const sources=computed(()=>[...props.data.sources].sort((a,b)=>a.order-b.order))
const targets=computed(()=>{const order=props.data.targetOrder||[...props.data.targets].sort((a,b)=>a.order-b.order).map(item=>item.id);return order.map(id=>props.data.targets.find(item=>item.id===id)!).filter(Boolean)})
const pairs=computed(()=>props.showAnswer?props.data.pairs:parseMatchingAnswer(props.modelValue,props.data))
function source(id:string){if(props.readonly)return;selected.value=selected.value===id?null:id}
function target(id:string){if(props.readonly)return;if(selected.value){emit('update:modelValue',matchingAnswer([...pairs.value.filter(pair=>pair.sourceId!==selected.value&&pair.targetId!==id),{sourceId:selected.value,targetId:id}]));selected.value=null}else{emit('update:modelValue',matchingAnswer(pairs.value.filter(pair=>pair.targetId!==id)))}}
function cancel(sourceId:string){if(!props.readonly)emit('update:modelValue',matchingAnswer(pairs.value.filter(pair=>pair.sourceId!==sourceId)))}
function geometry(){const element=root.value;if(!element)return;const bounds=element.getBoundingClientRect();lines.value=pairs.value.flatMap(pair=>{const a=Array.from(element.querySelectorAll<HTMLElement>('[data-source]')).find(item=>item.dataset.source===pair.sourceId),b=Array.from(element.querySelectorAll<HTMLElement>('[data-target]')).find(item=>item.dataset.target===pair.targetId);if(!a||!b)return [];const ar=a.getBoundingClientRect(),br=b.getBoundingClientRect();return [{key:pair.sourceId,x1:ar.left+ar.width/2-bounds.left,y1:ar.bottom-bounds.top,x2:br.left+br.width/2-bounds.left,y2:br.top-bounds.top}]})}
let observer:ResizeObserver|undefined
watch(()=>[props.data,props.modelValue,props.showAnswer],async()=>{selected.value=null;await nextTick();geometry()},{deep:true})
onMounted(()=>{observer=new ResizeObserver(geometry);if(root.value)observer.observe(root.value);window.addEventListener('resize',geometry);geometry()})
onUnmounted(()=>{observer?.disconnect();window.removeEventListener('resize',geometry)})
</script>
<template><section class="matching-question"><p v-if="!readonly" class="matching-instructions">先选上方图片，再选下方名称。点击名称或连接线可取消；Tab 和回车同样可操作。</p><div ref="root" class="matching-board"><div class="matching-row sources"><button v-for="(item,index) in sources" :key="item.id" type="button" :data-source="item.id" :aria-pressed="selected===item.id" :aria-label="`选择项目 ${index+1}${item.contentType==='text'?' '+item.text:''}`" :disabled="readonly" :class="{selected:selected===item.id,connected:pairs.some(pair=>pair.sourceId===item.id)}" @click="source(item.id)"><span class="matching-label">{{index+1}}</span><AssetImage v-if="item.contentType==='image'&&item.assetId" :asset-id="item.assetId" :alt="`项目 ${index+1}`" @load="geometry"/><span v-else>{{item.text}}</span></button></div><svg class="matching-lines" aria-hidden="true"><g v-for="line in lines" :key="line.key"><path :d="`M ${line.x1} ${line.y1} C ${line.x1} ${line.y1+40}, ${line.x2} ${line.y2-40}, ${line.x2} ${line.y2}`"/><path v-if="!readonly" class="line-hit" :d="`M ${line.x1} ${line.y1} C ${line.x1} ${line.y1+40}, ${line.x2} ${line.y2-40}, ${line.x2} ${line.y2}`" @click="cancel(line.key)"/></g></svg><div class="matching-row targets"><button v-for="(item,index) in targets" :key="item.id" type="button" :data-target="item.id" :aria-label="`${String.fromCharCode(65+index)} ${item.text}，${pairs.some(pair=>pair.targetId===item.id)?'已连接，点击取消或重新连接':'未连接'}`" :disabled="readonly" :class="{connected:pairs.some(pair=>pair.targetId===item.id)}" @click="target(item.id)"><b>{{String.fromCharCode(65+index)}}</b><AssetImage v-if="item.contentType==='image'&&item.assetId" :asset-id="item.assetId" :alt="`名称 ${String.fromCharCode(65+index)}`" @load="geometry"/><span v-else>{{item.text}}</span></button></div></div><div class="matching-footer"><span role="status">已连接 {{pairs.length}} / {{sources.length}} 组{{selected?' · 请选择下方名称':''}}</span><button v-if="!readonly" type="button" class="text-button" :disabled="!pairs.length" @click="selected=null;emit('update:modelValue','')">清空连接</button></div></section></template>
<style scoped>
.matching-question{margin:18px 0;min-width:0}.matching-instructions{font-size:12px;color:var(--muted);line-height:1.7}.matching-board{position:relative;padding:4px 0;min-width:0}.matching-row{position:relative;z-index:1;display:grid;grid-template-columns:repeat(v-bind('Math.min(sources.length,4)'),minmax(0,1fr));gap:12px}.matching-row button{border:1px solid var(--line);border-radius:10px;background:var(--surface);padding:12px;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;position:relative;color:var(--ink);font-size:14px;overflow-wrap:anywhere;min-height:64px}.sources button{min-height:100px}.matching-row img{width:100%;height:130px;object-fit:contain}.matching-row button.selected{outline:2px solid var(--blue);background:var(--blue-soft)}.matching-row button.connected{border-color:var(--blue)}.matching-row button:disabled{opacity:1;cursor:default}.matching-row button:focus-visible{outline:3px solid var(--blue);outline-offset:3px}.matching-label{align-self:flex-start;color:var(--muted);font-size:12px}.targets{margin-top:100px}.targets b{font-size:12px;color:var(--blue)}.matching-lines{position:absolute;inset:0;width:100%;height:100%;overflow:visible;z-index:2;pointer-events:none}.matching-lines path{fill:none;stroke:var(--blue);stroke-width:2}.matching-lines .line-hit{stroke:transparent;stroke-width:18;pointer-events:stroke;cursor:pointer}.matching-footer{display:flex;justify-content:space-between;align-items:center;margin-top:14px;font-size:12px;color:var(--muted)}@media(max-width:620px){.matching-row{gap:6px}.matching-row button{padding:7px;font-size:12px}.matching-row img{height:90px}}
</style>
